#!/usr/bin/env python3
import cyclopts
from pathlib import Path

app = cyclopts.App(
    config=cyclopts.Config(
        search_dirs=[Path.cwd()],
        config_name="pyproject.toml",
    )
)

@app.default
def main(
    name: str = None,
    greeting: str = "Hello",
    count: int = 1,
    verbose: bool = False,
) -> None:
    """A CLI with configuration from [tool.mycli] in pyproject.toml.

    Command-line arguments override config file values.
    """
    if name is None:
        name = "World"

    for _ in range(count):
        print(f"{greeting}, {name}!")

    if verbose:
        print(f"Config: greeting={greeting}, name={name}, count={count}")

if __name__ == "__main__":
    app()

